# 计算纯中文字符数并回填 words
allnotes = []
for date, arr in days.items():
    for n in arr:
        cn = len(re.findall(r'[\u4e00-\u9fff]', n['body']))
        n['words'] = cn
        allnotes.append(n)
        print(f"{date} {n['city']}: 中文字={cn}")

# 校验
forbidden = ['**','我刚回来','我亲测','我上次去','去了N次','N刷','本地人告诉我','只有去过才知道','闺蜜','学生党','穷游','特种兵','暴走','网红打卡','出片','必去','不去后悔','全网最全','全国第一','一定要去','闭眼冲','酸辣冲鼻很上头','焦香冒油','携程','美团','大众点评','小红书','抖音','快手','微信','支付宝','高德','百度','滴滴','祈福','灵验','许愿','有求必应','野味','现杀','现宰','石板路雨后长了青苔','下午四点光线斜照最好看','太美了','太香了','这里太美了','花费参考']

def check(n):
    errs = []
    if n['words'] < 1500: errs.append('中文字<1500')
    if '**' in n['body']: errs.append('含**')
    if '"' in n['body']: errs.append('含英文双引号')
    if '｜' not in n['imageTitle']: errs.append('imageTitle无｜')
    for b in ['🚄','📍','🏨','🍜','📸','💡']:
        if b not in n['body']: errs.append('缺'+b)
    if len(re.findall(r'\d️⃣', n['body'])) < 4: errs.append('避坑<4条')
    for w in forbidden:
        if w in n['body']: errs.append('禁词:'+w)
    return errs

allok = True
for n in allnotes:
    e = check(n)
    print(n['city'], '检查:', '✅ 通过' if not e else '❌ '+str(e))
    if e: allok = False

for date, arr in days.items():
    with open(f'notes_{date}.json', 'w', encoding='utf-8') as f:
        json.dump(arr, f, ensure_ascii=False, indent=2)
    print(f'已写入 notes_{date}.json')

print('\n全部通过 =', allok)
